50	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
51	import org.springframework.samples.petclinic.rest.dto.PetDto;
52	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
53	import org.springframework.samples.petclinic.rest.dto.VisitDto;
54	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
55	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
56	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
57	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
58	import org.springframework.samples.petclinic.service.ClinicService;
59	import org.springframework.security.access.prepost.PreAuthorize;
60	import org.springframework.web.bind.annotation.CrossOrigin;
61	import org.springframework.web.bind.annotation.RequestMapping;
62	import org.springframework.web.bind.annotation.RestController;
63	import org.springframework.web.util.UriComponentsBuilder;
64	
65	import jakarta.transaction.Transactional;
66	
67	/**
68	 * @author Vitaliy Fedoriv
69	 */
70	
71	@RestController
72	@CrossOrigin(exposedHeaders = "errors, content-type")
73	@RequestMapping("/api")
74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
77	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
78	
79	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
80	    private static final int MAX_OWNERS_PER_CITY = 50;
81	
82	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
83	    private static final int MAX_OWNERS_PER_DAY = 100;
84	
85	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
86	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
87	
88	    /** Fixed public holidays the business-day roll skips: the adjusted registration date never lands on one of these. */
89	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
90	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"), LocalDate.parse("2026-04-25"),
91	        LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
92	
93	    private final ClinicService clinicService;
94	
95	    private final OwnerMapper ownerMapper;
96	
97	    private final PetMapper petMapper;
98	
99	    private final VisitMapper visitMapper;
100	
101	    private final TelephoneNormalizer telephoneNormalizer;
102	
103	    private final AddressNormalizer addressNormalizer;
104	
105	    private final EmailNormalizer emailNormalizer;
106	
107	    private final IdentityKeyResolver identityKeyResolver;
108	
109	    private final HouseholdResolver householdResolver;
110	
111	    public OwnerRestControllerV1(ClinicService clinicService,
112	                                 OwnerMapper ownerMapper,
113	                                 PetMapper petMapper,
114	                                 VisitMapper visitMapper,
115	                                 TelephoneNormalizer telephoneNormalizer,
116	                                 AddressNormalizer addressNormalizer,
117	                                 EmailNormalizer emailNormalizer,
118	                                 IdentityKeyResolver identityKeyResolver,
119	                                 HouseholdResolver householdResolver) {
120	        this.clinicService = clinicService;
121	        this.ownerMapper = ownerMapper;
122	        this.petMapper = petMapper;
123	        this.visitMapper = visitMapper;
124	        this.telephoneNormalizer = telephoneNormalizer;
125	        this.addressNormalizer = addressNormalizer;
126	        this.emailNormalizer = emailNormalizer;
127	        this.identityKeyResolver = identityKeyResolver;
128	        this.householdResolver = householdResolver;
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
134	        Collection<Owner> owners;
135	        if (lastName != null) {
136	            owners = this.clinicService.findOwnerByLastName(lastName);
137	        } else {
138	            owners = this.clinicService.findAllOwners();
139	        }
140	        if (owners.isEmpty()) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        owners.forEach(this::populateHouseholdMemberCount);
144	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
145	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        populateHouseholdMemberCount(owner);
156	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
157	    }
158	
159	    /**
160	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
161	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
162	     * by the mapper alone.
163	     *
164	     * @param owner the owner to map
165	     * @return the owner DTO carrying its identity key
166	     */
167	    private OwnerDto toOwnerDto(Owner owner) {
168	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
169	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
170	        return ownerDto;
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Transactional
175	    @Override
176	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
177	        normalizeAndValidate(ownerFieldsDto);
178	        HttpHeaders headers = new HttpHeaders();
179	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
180	        populateDerivedFields(owner, ownerFieldsDto);
181	        requireUniqueIdentity(owner);
182	        requireHouseholdNotDuplicate(owner, ownerFieldsDto);
183	        flagPossibleDuplicate(owner, ownerFieldsDto);
184	        this.clinicService.saveOwner(owner);
185	        populateHouseholdMemberCount(owner);
186	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
187	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
188	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount(),
189	                owner.getHouseholdMemberCount(), owner.getRegistrationDate()),
190	            owner.getCustomerCode() + "-M" + String.format("%02d",
191	                FiscalYearResolver.fiscalYear(owner.getRegistrationDate()) % 100));
192	        OwnerDto ownerDto = toOwnerDto(owner);
193	        headers.setLocation(UriComponentsBuilder.newInstance()
194	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
195	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
196	    }
197	
198	    /**
199	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
200	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
201	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
202	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
203	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
204	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
205	     * last name and postcode, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The
206	     * owner is mutated in place; the caller applies the duplicate guards and saves it.
207	     *
208	     * @param owner          the newly mapped owner about to be saved
209	     * @param ownerFieldsDto the incoming owner payload
210	     */
211	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
212	        owner.setCustomerCode(deriveUniqueCustomerCode(owner));
213	        owner.setNamesakeCount(countNamesakes(owner));
214	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
215	        assignHouseholdId(owner);
216	    }
217	
218	    /**
219	     * Derives an owner's {@code customerCode} and de-duplicates it against the owners that already exist. The base code
220	     * is the pure derivation (see {@link IdentityKeyResolver#deriveCustomerCode}); when it collides with an existing
221	     * owner's {@code customerCode} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
222	     * makes the whole code unique. Evaluated before the new owner is saved, so the collision check reflects only owners
223	     * that predate this create; distinct owners therefore always receive distinct customer codes.
224	     *
225	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
226	     * @return the de-duplicated customer code, unique across all existing owners
227	     */
228	    private String deriveUniqueCustomerCode(Owner owner) {
229	        String base = identityKeyResolver.deriveCustomerCode(owner);
230	        Collection<Owner> existing = this.clinicService.findAllOwners();
231	        String candidate = base;
232	        int n = 2;
233	        while (isCustomerCodeInUse(candidate, existing)) {
234	            candidate = base + "-" + n;
235	            n++;
236	        }
237	        return candidate;
238	    }
239	
240	    private boolean isCustomerCodeInUse(String customerCode, Collection<Owner> existing) {
241	        return existing.stream().anyMatch(other -> customerCode.equals(other.getCustomerCode()));
242	    }
243	
244	    /**
245	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
246	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
247	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
248	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
249	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
250	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
251	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
252	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
253	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
254	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
255	     * assigned (see {@link #requireUniqueIdentity}).
256	     *
257	     * @param ownerFieldsDto the incoming owner payload, mutated in place
258	     * @throws MissingOwnerFieldsException if any required field is missing or blank
259	     */
260	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
261	        normalizeAddress(ownerFieldsDto);
262	        validateRequiredFields(ownerFieldsDto);
263	        validatePostcode(ownerFieldsDto);
264	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
265	        ownerFieldsDto.setTelephone(telephone);
266	        requireCityHasCapacity(ownerFieldsDto.getCity());
267	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
268	        ownerFieldsDto.setRegistrationDate(registrationDate);
269	        requireDailyLimitNotReached(registrationDate);
270	        normalizeEmail(ownerFieldsDto);
271	    }
272	
273	    /**
274	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
275	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
276	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
277	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
278	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
279	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
280	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
281	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
282	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
283	     *
284	     * @param ownerFieldsDto the incoming owner payload, mutated in place
285	     */
286	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
287	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
288	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
289	        if (!line1.isEmpty()) {
290	            ownerFieldsDto.setAddressLine1(line1);
291	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
292	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
293	        }
294	        else {
295	            ownerFieldsDto.setAddressLine1(null);
296	            ownerFieldsDto.setAddressLine2(null);
297	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
298	        }
299	    }
300	
301	    /**
302	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
303	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
304	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
305	     * place so the caller can map and save it directly.
306	     *
307	     * @param ownerFieldsDto the incoming owner payload, mutated in place
308	     */
309	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
310	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
311	    }
312	
313	    /**
314	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
315	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday, a Sunday
316	     * or a listed public holiday (see {@link #PUBLIC_HOLIDAYS}) it is rolled forward one day at a time until it lands on
317	     * a non-holiday weekday. The returned date is always a business day. A supplied date later than the current server
318	     * date is rejected.
319	     *
320	     * @param ownerFieldsDto the incoming owner payload
321	     * @return the effective registration date rolled forward onto a business day
322	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
323	     */
324	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
325	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
326	        if (effective == null) {
327	            effective = LocalDate.now();
328	        }
329	        else if (effective.isAfter(LocalDate.now())) {
330	            throw new FutureRegistrationDateException(
331	                "the registration date must not be later than the current server date");
332	        }
333	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY
334	            || PUBLIC_HOLIDAYS.contains(effective)) {
335	            effective = effective.plusDays(1);
336	        }
337	        return effective;
338	    }
339	
340	    /**
341	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
342	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
343	     * further owner may be created for that day.
344	     *
345	     * @param registrationDate the adjusted business-day registration date of the owner being created
346	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
347	     */
348	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
349	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
350	            throw new DailyOwnerLimitExceededException(
351	                "the maximum number of owners for today has already been reached");
352	        }
353	    }
354	
355	    /**
356	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
357	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
358	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
359	     * warning threshold) so both express the same per-day count in one place.
360	     *
361	     * @param registrationDate the adjusted business-day registration date to count owners for
362	     * @return the number of existing owners registered on that day
363	     */
364	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
365	        return this.clinicService.findAllOwners().stream()
366	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
367	            .count();
368	    }
369	
370	    /**
371	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
372	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
373	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
374	     * reflects only owners that predate it.
375	     *
376	     * @param registrationDate the adjusted business-day registration date of the owner being created
377	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
378	     */
379	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
380	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
381	    }
382	
383	    /**
384	     * Counts how many existing owners already share the given owner's first and last name, compared
385	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
386	     * create; it is zero when the owner's name is unique.
387	     *
388	     * @param owner the newly mapped owner about to be saved
389	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
390	     */
391	    private int countNamesakes(Owner owner) {
392	        String firstName = owner.getFirstName();
393	        String lastName = owner.getLastName();
394	        return (int) this.clinicService.findAllOwners().stream()
395	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
396	                && lastName.equalsIgnoreCase(existing.getLastName()))
397	            .count();
398	    }
399	
400	    /**
401	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
402	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
403	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
404	     *
405	     * <p>The address is checked after normalization has composed the canonical {@code address} from whichever form was
406	     * supplied, so a blank {@code address} here means the owner supplied neither a non-blank {@code addressLine1} nor a
407	     * flat {@code address}.
408	     *
409	     * @param ownerFieldsDto the owner payload to validate
410	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
411	     */
412	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
413	        List<String> missingFields = new ArrayList<>();
414	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
415	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
416	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
417	        requireText(missingFields, "city", ownerFieldsDto.getCity());
418	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
419	        if (!missingFields.isEmpty()) {
420	            throw new MissingOwnerFieldsException(missingFields);
421	        }
422	    }
423	
424	    private void requireText(List<String> missingFields, String fieldName, String value) {
425	        if (value == null || value.isBlank()) {
426	            missingFields.add(fieldName);
427	        }
428	    }
429	
430	    /**
431	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
432	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
433	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
434	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
435	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
436	     *
437	     * @param ownerFieldsDto the incoming owner payload
438	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
439	     */
440	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
441	        String postcode = ownerFieldsDto.getPostcode();
442	        if (postcode == null) {
443	            return;
444	        }
445	        Region region = Region.forCity(ownerFieldsDto.getCity());
446	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
447	            throw new InvalidPostcodeException(
448	                "postcode " + postcode + " is not valid for the city's region " + region.name());
449	        }
450	    }
451	
452	    /**
453	     * Rejects creating an owner whose whole derived {@code identityKey} (see
454	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
455	     * duplicate only when its normalized telephone, email and {@code householdId} all match another owner's. It runs
456	     * after the household id has been assigned, so the key reflects the household the owner belongs to. Owners that
457	     * share only their household (same last name and postcode, different telephone) are not caught here but by the
458	     * separate household-duplicate guard (see {@link #requireHouseholdNotDuplicate}). Owners that have been
459	     * soft-deleted (see {@link #deleteOwner}) are ignored, so a matching identity that belongs only to a deleted
460	     * owner does not block the create.
461	     *
462	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
463	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
464	     */
465	    private void requireUniqueIdentity(Owner owner) {
466	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
467	        boolean inUse = this.clinicService.findAllOwners().stream()
468	            .filter(existing -> !existing.isDeleted())
469	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
470	        if (inUse) {
471	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
472	        }
473	    }
474	
475	    /**
476	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared both the hard-duplicate
477	     * guard (see {@link #requireUniqueIdentity}) and the household-duplicate guard (see
478	     * {@link #requireHouseholdNotDuplicate}), so it is still being created; this only records a warning. A declared
479	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
480	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
481	     * duplicate when some existing owner shares its last name (compared case-insensitively) and its postcode but
482	     * carries a different telephone. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
483	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
484	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
485	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
486	     *
487	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
488	     * @param ownerFieldsDto the incoming owner payload
489	     */
490	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
491	        owner.setPossibleDuplicate(false);
492	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
493	            return;
494	        }
495	        String postcode = owner.getPostcode();
496	        if (postcode == null || postcode.isBlank()) {
497	            return;
498	        }
499	        String lastName = owner.getLastName();
500	        String telephone = owner.getTelephone();
501	        for (Owner existing : this.clinicService.findAllOwners()) {
502	            if (lastName.equalsIgnoreCase(existing.getLastName())
503	                && postcode.equals(existing.getPostcode())
504	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
505	                owner.setPossibleDuplicate(true);
506	                owner.setPossibleDuplicateOf(existing.getId());
507	                return;
508	            }
509	        }
510	    }
511	
512	    /**
513	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
514	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
515	     *
516	     * @param city the city of the owner being created
517	     * @throws OwnerCityFullException if the city already contains 50 or more owners
518	     */
519	    private void requireCityHasCapacity(String city) {
520	        long cityOwners = this.clinicService.findAllOwners().stream()
521	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
522	            .count();
523	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
524	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
525	        }
526	    }
527	
528	    /**
529	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
530	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
531	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
532	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
533	     * such owners never match one another as a household.
534	     *
535	     * @param owner the newly mapped owner about to be saved
536	     */
537	    private void assignHouseholdId(Owner owner) {
538	        String postcode = owner.getPostcode();
539	        if (postcode == null || postcode.isBlank()) {
540	            owner.setHouseholdId(null);
541	            return;
542	        }
543	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
544	    }
545	
546	    /**
547	     * Rejects creating an owner that would join an existing household it has not declared. Because the household is
548	     * keyed on the last name and postcode (see {@link #assignHouseholdId}), any existing owner carrying the same
549	     * derived {@code householdId} is a member of the same household. A second such owner is a household duplicate and is
550	     * rejected, unless the payload sets {@code sharesHousehold} to {@code true}, which declares the owner a genuine
551	     * household member and lets the create proceed. An owner with no household ({@code null} householdId, i.e. created
552	     * without a postcode) can never be a household duplicate. Owners that have been soft-deleted (see
553	     * {@link #deleteOwner}) are ignored, so a household whose only member has been deleted does not block the create.
554	     *
555	     * @param owner          the newly mapped owner about to be saved, with its household id already assigned
556	     * @param ownerFieldsDto the incoming owner payload
557	     * @throws DuplicateOwnerException if an existing owner already belongs to this household and the create did not
558	     *                                 declare {@code sharesHousehold}
559	     */
560	    private void requireHouseholdNotDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
561	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
562	            return;
563	        }
564	        String householdId = owner.getHouseholdId();
565	        if (householdId == null) {
566	            return;
567	        }
568	        boolean sharedByExisting = this.clinicService.findAllOwners().stream()
569	            .filter(existing -> !existing.isDeleted())
570	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
571	        if (sharedByExisting) {
572	            throw new DuplicateOwnerException("an owner in the same household already exists");
573	        }
574	    }
575	
576	    /**
577	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
578	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
579	     * household is counted as a household of one.
580	     *
581	     * @param owner the owner whose household size should be resolved
582	     */
583	    private void populateHouseholdMemberCount(Owner owner) {
584	        String householdId = owner.getHouseholdId();
585	        if (householdId == null) {
586	            owner.setHouseholdMemberCount(1);
587	            return;
588	        }
589	        long members = this.clinicService.findAllOwners().stream()
590	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
591	            .count();
592	        owner.setHouseholdMemberCount((int) members);
593	    }
594	
595	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
596	    @Override
597	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
598	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
599	        if (currentOwner == null) {
600	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
601	        }
602	        validatePostcode(ownerFieldsDto);
603	        currentOwner.setAddress(ownerFieldsDto.getAddress());
604	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
605	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
606	        currentOwner.setCity(ownerFieldsDto.getCity());
607	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
608	        currentOwner.setLastName(ownerFieldsDto.getLastName());
609	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
610	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
611	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
612	        this.clinicService.saveOwner(currentOwner);
613	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
614	    }
615	
616	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
617	    @Transactional
618	    @Override
619	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
620	        Owner owner = this.clinicService.findOwnerById(ownerId);
621	        if (owner == null) {
622	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
623	        }
624	        owner.setDeleted(true);
625	        this.clinicService.saveOwner(owner);
626	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
627	    }
628	
629	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
630	    @Override
631	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
632	        Owner owner = this.clinicService.findOwnerById(ownerId);
633	        if (owner == null) {
634	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
635	        }
636	        HttpHeaders headers = new HttpHeaders();
637	        Pet pet = petMapper.toPet(petFieldsDto);
638	        owner.setId(ownerId);
639	        pet.setOwner(owner);
640	        pet.getType().setName(null);
641	        this.clinicService.savePet(pet);
642	        PetDto petDto = petMapper.toPetDto(pet);
643	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
644	            .buildAndExpand(pet.getId()).toUri());
645	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
646	    }
647	
648	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
649	    @Override
650	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
651	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
652	        if (currentOwner != null) {
653	            Pet currentPet = this.clinicService.findPetById(petId);
654	            if (currentPet != null) {
655	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
656	                currentPet.setName(petFieldsDto.getName());
657	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
658	                this.clinicService.savePet(currentPet);
659	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
660	            }
661	        }
662	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
663	    }
664	
665	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
666	    @Override
667	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
668	        HttpHeaders headers = new HttpHeaders();
669	        Visit visit = visitMapper.toVisit(visitFieldsDto);
670	        Pet pet = new Pet();
671	        pet.setId(petId);
672	        visit.setPet(pet);
673	        this.clinicService.saveVisit(visit);
674	        VisitDto visitDto = visitMapper.toVisitDto(visit);
675	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
676	            .buildAndExpand(visit.getId()).toUri());
677	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
678	    }
679	
680	
681	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
682	    @Override
683	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
684	        Owner owner = this.clinicService.findOwnerById(ownerId);
685	        if (owner != null) {
686	            Pet pet = owner.getPet(petId);
687	            if (pet != null) {
688	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
689	            }
690	        }
691	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
692	    }
693	}
